{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "Instance Metadata Service Version 1 is enabled on the EC2 instance, which can be used to obtain instance metadata without authentication."
    }
    ,
    {
      "check_id": "CKV_AWS_135",
      "title": "Ensure that EC2 is EBS optimized",
      "resource": "aws_instance.web",
      "severity": "LOW",
      "explanation": "The EC2 instance is not EBS optimized, which can impact performance."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"web\" {\n  ami                    = \"${var.ami}\"\n  instance_type          = \"t2.micro\"\n  subnet_id              = \"${aws_subnet.public-subnet.id}\"\n  vpc_security_group_ids = [\"${aws_security_group.sgweb.id}\"]\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n  ebs_optimized = true\n}",
  "fix_summary": "Added metadata_options to disable IMDSv1 and enabled EBS optimization for the EC2 instance."
}
